Method.Implementation:
	set tSC = $$$OK

	Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup(usrNm, passwd)
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "svnUpdate - CheckInSqlFileFile: " _ fileNm)

	Do ##class(%File).Delete(fileNm)
	Set cmd=""
	if (rev '= "")
	{

		Set cmd= $$$SVNUPDATE _ " --revision " _ rev
	}
	else
	{	
		Set cmd= $$$SVNUPDATE	
		//  set tSC = $$$ERROR($$$GeneralError, "Checkout: Revision number is required") 
	}	
	Set cmd= cmd _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _  fileNm 

	Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	if (status '= 0)
	{
		set tSC = $$$ERROR($$$GeneralError, $$$SVNUPDATE _ " --revision " _ rev _ " failed")
	}
	if ##class(%File).Exists(fileNm)
	{
		if (rev '= "")
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Checked out latest version of " _ fileNm)
		}
		else
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Checked out " _ fileNm _ ", version: " _ rev)
		}
	}
	else {
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not find file in SVN: " _ fileNm)
		set tSC = $$$ERROR($$$GeneralError, "Could not find file in SVN: " _ fileNm)
	}

 	Quit tSC

 set tSC = $$$OK
 set $NAMESPACE = nmSp
 set statMsg = Oper
 If FileName = "" {
		set statMsg = statMsg _ ": " _("File Name is empty. Unable to continue.")
		Quit
 } Else {
		If Oper = "Export" {
			#; If directory doesn't exists, create it now
			Set Dir = ##class(%File).GetDirectory(FileName,1)
			Set tSC = ##class(%File).CreateDirectoryChain(Dir)
			If tSC '= 1 {
				set statMsg = statMsg _ ": " _(Dir_": "_"Could not create this directory. Please check the directory and try again.")
				Quit
			}
		}  
 }

  set metaData = ""
  SET myquery=1
  SET myquery(1)="SELECT * FROM " _ ..SchemaName_"."_TableName
  SET rset = ##class(%SQL.Statement).%New()
  SET tSC = rset.%Prepare(.myquery)
  IF tSC'=1 {set statMsg = statMsg _ ", " _ "%Prepare failed:" DO $System.Status.DisplayError(tSC) QUIT tSC}
  SET x=rset.%Metadata.columns.Count()
  SET x=1
  WHILE rset.%Metadata.columns.GetAt(x) {
    SET column=rset.%Metadata.columns.GetAt(x)
    set metaData = metaData _ x _"^" _ column.colName _"^" _ column.ODBCType _"^" _ column.precision _","
    // WRITE !,x," ",column.colName," is data type ",column.ODBCType
    // WRITE " with a size of ",column.precision," and scale = ",column.scale
    SET x=x+1 
  }
  set TotalColumns = x
  // WRITE !,"End of metadata: " _ metaData
  set Columns = $LISTFROMSTRING(metaData)

	set Charset = 1 // "<Device Default>"
	set StringQuote = "double"
	set DateFormat = 1 // "MM/DD/{YY}YY"
	set TimeFormat = 1 // "hh:mm:ss"
	set TimeStampFormat = 1
	set HasHeaders = 1	
	set DeferIndices = 1


	set mgr = ""
		If Oper = "Export" {
			set mgr = ##class(%SQL.Export.Mgr).%New()
		}
		Else {
		  Set mgr = ##class(%SQL.Import.Mgr).%New()
		}
		If mgr = "" {
			If Oper["Import" { Set tmsg = "Error creating object for SQL Import." } 
			Else { Set tmsg = "Error creating object for SQL Export." }
			set statMsg = statMsg _ ", " _(tmsg)
			Quit
		}


		Set mobj = ##class(%SQL.Manager.API).%New()
		set schemaName = ..SchemaName
		set tableName = TableName
		Set mgr.IQN=$$$BuildIQN(schemaName,tableName)
		Set tSC = mobj.CheckIdentifier(.schemaName)
		Set tSC = mobj.CheckIdentifier(.tableName)
		Set classname = mobj.FindClassName(schemaName_"."_tableName)
		If classname = "" {
			set statMsg = statMsg _ ", " _("Class name is empty. " _ schemaName_"."_tableName) 
			Quit
		}
		Set mgr.FileName = FileName
		// Set mgr.Charset = Charset
		Set mgr.TableName = schemaName_"."_tableName
		Set mgr.ClassName = classname
		Set mgr.Delimiter = ","
		Set delim = StringQuote
		Set mgr.StringQuote = $s(delim="":"",delim="double":"""",1:"'")
	 	Set mgr.DateFormat = DateFormat
	 	Set mgr.TimeFormat = TimeFormat
	 	Set mgr.TimeStampFormat = TimeStampFormat
	 	Set mgr.NoCheck = 1
	  	Set mgr.HasHeaders = HasHeaders
		For i = 1:1:TotalColumns {
			Set coldata = $li(Columns,i)
			Set colname = $p(coldata,"^",2)
			Set datatype = $p(coldata,"^",3)
		 	Set tSC = mobj.CheckIdentifier(.colname)
		 	Do mgr.ColumnNames.Insert(colname)

		 	if (datatype = 2) { set datatype="D" }
	        elseif (datatype = 8 ) { set datatype="T" }
	        elseif (datatype = 9 ) { set datatype="TS" }
		    elseif (datatype = 4 ) { set datatype= "N" }
			else { set datatype ="S"}

		 	Do mgr.ColumnTypes.Insert(datatype)
		 	// set statMsg = statMsg _ ", " _coldata _", " _ colname _", " _datatype
		}

		Set rows = 1000
		Set done = 0
		Set total = 0
		Set totalbytes = 0
		Set totalinserted = 0
		Set numerr = 0
		Set size = 0
		Set header = ""
		set statMsg = statMsg _ ", " _Oper _ "- ClassName: " _ mgr.%ClassName(1)

		set oldID = $IO
        // This generates output to console; causes javascript to throw error
        OPEN "/dev/null/" 
        USE "/dev/null/"
        try {
		  If Oper = "Export" {
			Set tSC = mgr.GenerateExportRoutine()
			If tSC '= 1 {
				Set tmsg = "Error generating export routine: "_tSC
				set statMsg = statMsg _ ", " _(tmsg)
				Quit
			}
			// set statMsg = statMsg _ ", " _"Open Export " _ tSC
			Set tSC = mgr.OpenExport()
			If $$$ISERR(tSC) {
				Set ErrMsg = "Unable to open export file"

				set statMsg = statMsg _ ", " _ErrMsg _" , " _ tSC
				QUIT
			} Else {
				// set statMsg = statMsg _ ", " _"Export Size"
				Set sta = mgr.GetExportSize(.size)
				If size = 0 {
					set statMsg = statMsg _ ", " _"No data to export, file is 0 bytes"
					QUIT
				} Else {
					Set tSC = $$$OK
					Do {
						Set tSC = mgr.ExportRows(.rows,.done)
						Set total = total + rows
						If $$$ISERR(tSC) {
							set statMsg = statMsg _ ", " _($System.Status.GetErrorText(tSC)) 
							Quit
						}
					} While done = 0
					If $$$ISOK(tSC) {
						set statMsg = statMsg _ ", " _$$$FormatText("Completed at %1",$zdt($h))
					} Else {
						set statMsg = statMsg _ ", " _"Error occurred during export. " _ tSC
						QUIT
					}
					set statMsg = statMsg _ ", " _$$$FormatText("Exported: %1 rows",total)
				}
				Do mgr.CloseExport()
			}
			Do mgr.DeleteExportRoutine()
			set statMsg = statMsg _ ", " _"Export complete"
		}

		Else {	// Import
		 	Set mgr.DeferIndices = DeferIndices
			Set tSC = mgr.GenerateImportRoutine()
			If tSC '= 1 {
				Set tmsg = "ERROR generating import routine: "_tSC
				set statMsg = statMsg _ ", " _(tmsg)
				Quit
			}
			set statMsg = statMsg _ ", " _"Open Import After GenerateImportRoutine: " _ tSC
			set statMsg = statMsg _ ", " _"File size: " _ mgr.FileSize()
			Set tSC = mgr.OpenImport()
			If $$$ISERR(tSC) {
				Set ErrMsg = "ERROR Unable to open import file: " _ tSC				
				set statMsg = statMsg _ ", " _(ErrMsg )
				Quit
			} Else {
				set statMsg = statMsg _ ", " _"ReadHeader"
				If mgr.HasHeaders = 1 Set sta = mgr.ReadHeader(.header,.size)

				Do {
					set statMsg = statMsg _ ", " _"ImportRows"
					Set tSC = mgr.ImportRows(.rows,.inserted,.bytes,.done,.numerr,total)
					Set total = total + rows
					Set totalinserted = totalinserted + inserted
					Set totalbytes = totalbytes + bytes
					If $$$ISERR(tSC) {
						set statMsg = statMsg _ ", " _($System.Status.GetErrorText(tSC)) 
						Quit
					}
				} While done = 0
				set statMsg = statMsg _ ", " _"BuildIndices"
				Do mgr.BuildIndices()
				If mgr.ErrorCount() > 0 {				
					Set ErrMsg = "ERROR in BuildIndices, # of errors: " _ mgr.ErrorCount()
					set statMsg = statMsg _ ", " _(ErrMsg) 
					Quit

				} Else {
					set statMsg = statMsg _ ", " _"After Build Ind"
					If $$$ISOK(tSC) {
						set statMsg = statMsg _ ", " _ $$$FormatText("Completed at %1",$zdt($h))
					} Else {
						Set ErrMsg = "Error occurred during import. " _ tSC	
						set statMsg = statMsg _ ", " _(ErrMsg) 
						Quit	 	
					}
					set statMsg = statMsg _ ", " _($$$FormatText("Imported: %1 rows",totalinserted))

				}	 
				set statMsg = statMsg _ ", " _"Close"	
				Do mgr.CloseImport(0)
			}
			Do mgr.DeleteImportRoutine()
			set statMsg = statMsg _ ", " _"Import complete"
			// Do ..insertImplRecord(usrNm, passwd, TableName, nmSp , fName, settingRev, srcCtrlFile, env , $ZDATETIME($HOROLOG,3, 1))

		}
		// WRITE !, statMsg
  } catch exp
  {
	  set statMsg = statMsg _ ", " _ "This is the CATCH exception handler"
	  set statMsg = statMsg _ ", " _mgr.ErrorCount() 
      IF 1=exp.%IsA("%Exception.SystemException") {
         set statMsg = statMsg _ ", " _ "System exception"
         set statMsg = statMsg _ ", " _ "Name: "_$ZCVT(exp.Name,"O","HTML")
         set statMsg = statMsg _ ", " _ "Location: "_exp.Location
         set statMsg = statMsg _ ", " _ "Code: "_exp.Code
         set statMsg = statMsg _ ", " _ "Data: "_exp.Data
      }
      ELSE { set statMsg = statMsg _ ", " _ "not a system exception!!"}
      set statMsg = statMsg _ ", " _ "$ZERROR: "_$ZERROR
      set statMsg = statMsg _ ", " _ "$ECODE: "_$ECODE
      WRITE !, statMsg
  }
  CLOSE "/dev/null/"

 	OPEN oldID
 	USE oldID
  return tSC

 try
 {

	Set tSC = $$$OK 
	set fName = nmSp _ "-" _ compName _".txt"
	set tempFile = ..DeployDirectory _ ..SqlTableDirectory _ env _"/" _ fName

	if ('##class(%File).Exists(tempFile))
	{
		set tSC = $$$ERROR("Can't open file: " _ tempFile)
		RETURN tSC
	}

    set fullPath = $$$USRRELEASEBASEDIR _ userNm _ $$$SVNSRCTRUNK _ ..SqlTableDirectory _ env _"/"
    IF ' ##class(%File).DirectoryExists(fullPath)
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Creating: " _ fullPath)
	     set tStat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup(userNm, passwd)
	 }


	set fullPath = fullPath _ fName
	Do ##class(%File).CopyFile(tempFile, fullPath)

	if (##class(%File).Exists(fullPath))
	{
		Set cmd = $$$SVNINFO _ " --username " _ userNm _ " --password '" _ passwd _ "' " _ fullPath
		Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(fullPath _ " svn info:" _ stat)

		If stat '= 0 	
		{
			// files not in svn, add the file
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( $$$SVNINFO _" returned no information" )
			Set cmd = $$$SVNADD _ " --username " _ userNm _ " --password '" _ passwd _ "' " _  fullPath  
			Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("svn add:" _ stat)
			If stat '= 0
			{
				Set tSC = $$$ERROR($$$EnsErrGeneral, "SVN add error for " _ fullPath)
				Return tSC
			}
		}
		set tempFile = ##class(%Library.File).TempFilename()
		set commentFile = ##class(%Library.File).TempFilename()
		Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).WriteToFile(commentFile, cmt)

		Set cmd = $$$SVNCOMMIT _ " --no-auth-cache --non-interactive --username " _ userNm _ " --password '" _ passwd  _ "' -F "" " _ commentFile _ " "" " _ fullPath _ " > " _ tempFile
		Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckinFiles: commit stat: " _ stat _ " file: " _ tempFile)

		if stat '= 0
		{
			  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("SVN commit error: " _ $$$SVNCOMMIT _ " " _ fullPath)
			  Set tSC = $$$ERROR($$$EnsErrGeneral, "SVN commit error")
			  Do ##class(%Library.File).Delete(tempFile)
		}
		else
		{
			Set tSC = $$$OK
			set tComment = ##class(%Stream.TmpCharacter).%New()
			Do ##class(IHC.ITF.ITFCOMMON.Utility).findStringInFile(tempFile, "Committed", tComment)

			Do tComment.Rewind()
	    	set len = 32656
	    	#dim sc as %Status
	    	set commitComment = tComment.Read(.len, .sc)
	    	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("SVN commit: " _ commitComment)
	    	set retStr = fullPath _ " - " _ commitComment
	    	Do ##class(%Library.File).Delete(tempFile)
	    	if ($L(retStr) = 0)
	    	{
		    	set retStr = "SVN commit complete, file may not be modified"
	    	}
		}
	}
	else
	{
		set tSC = $$$ERROR("Can't open file: " _ fullPath)
	}

 } catch err
 {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Error: " _ err.Name _ " " _ err.Data _ " " _ ..DeployDirectory)
 }
 return tSC


	set fileNm = $$$USRRELEASEBASEDIR _ usrNm _ $$$SVNSRCTRUNK _ ..SqlTableDirectory _ env _"/" _ nmSp _ "-" _ compName _".txt"

    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "GetVersions: " _ fileNm _", Name: " _ compName _ "$")

	Do ##class(%File).Delete(fileNm)
	Set cmd= $$$SVNUPDATE _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _  fileNm 

	Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	if (status '= 0)
	{
		set fileInfo = $$$SVNUPDATE _ " failed for: " _ fileNm
	}
	if ##class(%File).Exists(fileNm)
	{
			set tempFile = 	fileNm _ "Temp"
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Checked out " _ fileNm)
			Set cmd= $$$SVNINFO _ fileNm _ " >> " _ tempFile

			Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
			if (status =0)
			{
	        	Set cmd=  $$$SVNLOG _" --username " _ usrNm _ " --password '" _ passwd _ "' " _ fileNm _ " >> " _ tempFile 

				Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	  			if ((status =0) && (##class(%File).Exists(tempFile)) )
	  			{
         			// Call the function to get svn information
         			Set fileInfo = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).GetFileContent(tempFile)       
	  			}
	  			else
	  			{
		  			SET fileInfo = "svn command :" _ $$$SVNLOG _ " failed: " _ $$$SVNLOG
	  			}
			}
			else
	  			{
		  			SET fileInfo = "svn command :" _ $$$SVNINFO _ " failed: " _ $$$SVNLOG
	  			}
	}
	else {
  			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not find file in SVN: " _ fileNm)


	  		set fileInfo = "Could not find file in SVN: " _ fileNm

 	}

	Quit fileInfo

set sc = $$$OK
set retStr = ""
try {
	set $NAMESPACE = nmSp
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetSqlFileFromSvn: " _ compName)

	set direc = ..DeployDirectory _ ..SqlTableDirectory _ env _"/"
	IF ' ##class(%File).DirectoryExists(direc)
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Creating: " _ direc)
		 Do ##class(%File).CreateDirectoryChain(direc)
	     set tStat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup(usrNm, passwd)
	 }
	set fName = nmSp _ "-" _ compName _".txt" 
	set tempFile = direc _  fName
	set srcCtrlFile = $$$USRRELEASEBASEDIR _ usrNm _ $$$SVNSRCTRUNK _ ..SqlTableDirectory _ env _"/" _ fName
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetSqlFileFromSvn - File: " _ tempFile _", Src ctrl: " _ srcCtrlFile)


	Set sc = ..svnUpdate(srcCtrlFile, usrNm , passwd, "" )
	if ($$$ISOK(sc))
	{
		Do ##class(%File).CopyFile(srcCtrlFile, tempFile)
		set retStr = "; Copied from the Source Control: " _ tempFile
	}
	return sc

} catch(err)
{
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Exception: Could not create setting files " _ err)
	set sc = $$$ERROR("Could not create setting files " _ err.Data)
}			
return sc

	set tSC = $$$OK
	try {

		 	NEW $NAMESPACE
     		set $NAMESPACE = "ITFCOMMON"
	 		set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
	 		set depCl.Username = usrNm
		 	set depCl.Password = passwd
		 	Set depCl.Location = ..WSLocation
	 		set tSC = depCl.UpdateComponentImpl(compNm, nmSp, fileName, rev, fileInfo, env, dt, usrNm)
	 		return tSC
	} catch err
	{
		 		If $ZERROR["<ZSOAP>" {
                	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in updating Component in DB: " _ depCl.SoapFault.Reason.Text)
		 		} Else {
            		Set tSC=$$$ERROR($$$CacheError,$ZERROR)
		 		}
	}
	return tSC
